def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        base = DAILY_SALARY * 0.22
        if hp <= 2 or no_water_days >= 2:
            base = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    urgent_count = 0
    rich_aggressive = 0
    for oid, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        pbid = prev.get('bid')
        if pbid is not None:
            prev_bids.append(float(pbid))
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
            urgent_count += 1
        if opp.get('budget', 0) > budget and pbid is not None and pbid >= DAILY_SALARY * 0.9:
            rich_aggressive += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = 1.0 - ((float(supply) - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY))
    if scarcity < 0.0:
        scarcity = 0.0
    if scarcity > 1.0:
        scarcity = 1.0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 1

    days_left = 10 - int(day) + 1
    reserve_target = max(0.0, days_left * DAILY_SALARY * 0.28)
    spendable = max(0.0, budget - reserve_target)

    base = DAILY_SALARY * (0.22 + 0.28 * scarcity)

    if highest_prev > 0:
        if highest_prev >= 120:
            base = min(base, DAILY_SALARY * 0.42)
        elif highest_prev >= 80:
            base = max(base, min(DAILY_SALARY * 0.62, avg_prev * 0.72))
        else:
            base = max(base, highest_prev + 2.0)

    if urgent_count >= 2:
        base += 8.0
    elif urgent_count == 1:
        base += 4.0

    if rich_aggressive >= 2 and danger == 0:
        base *= 0.82

    if danger >= 5:
        bid = max(base, highest_prev + 4.0, DAILY_SALARY * 0.95)
    elif danger >= 3:
        bid = max(base, highest_prev + 2.0, DAILY_SALARY * 0.72)
    elif danger >= 1:
        bid = max(base, DAILY_SALARY * 0.48)
    else:
        bid = base

    if float(supply) >= 23.0 and danger == 0:
        bid *= 0.72
    elif float(supply) >= 20.0 and danger <= 1:
        bid *= 0.84
    elif float(supply) <= 16.0:
        bid *= 1.12

    if int(day) >= 8:
        if hp <= 4 or no_water_days >= 1:
            bid = max(bid, DAILY_SALARY * 0.85)
        else:
            bid *= 0.95

    cap = budget
    if spendable > 0:
        cap = min(budget, spendable + DAILY_SALARY * 0.65)
    bid = min(bid, cap)
    bid = max(0.0, min(budget, bid))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = day_context['supply']
    day = day_context['day']

    # Identify alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no opponents, take a safe fraction of budget
    if not alive_opps:
        return max(0.0, min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace (immediate reaction only)
    yesterday_bids = []
    yesterday_info = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            b = prev.get('bid')
            yesterday_bids.append(b)
            yesterday_info.append((oid, b, prev.get('hp_after', None), prev.get('budget_after', None)))

    # Estimate opponent pressure: how aggressive yesterday was among those alive
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    # Determine baseline bid aggressiveness
    # Cindy/Eric survived with very high average bids (~110-125), so if we see high bids yesterday,
    # we avoid matching them fully unless our HP is critical.
    critical_hp = my_status.get('hp', 0) <= 2
    low_hp = my_status.get('hp', 0) <= 4

    # Supply pressure: higher supply reduces need to overbid
    supply_ratio = (float(supply) - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))
    if supply_ratio < 0.0:
        supply_ratio = 0.0
    if supply_ratio > 1.0:
        supply_ratio = 1.0

    # If opponents were bidding very high yesterday, they likely continued to overbid.
    # We bid just enough to stay competitive.
    high_pressure = highest_prev_bid >= DAILY_SALARY * 1.15 or avg_prev_bid >= DAILY_SALARY

    # Compute target bid
    if critical_hp:
        # Must secure water; bid near salary but not beyond budget
        target = DAILY_SALARY * (0.85 + 0.1 * (1.0 - supply_ratio))
    elif low_hp:
        target = DAILY_SALARY * (0.6 + 0.25 * (1.0 - supply_ratio))
    else:
        if high_pressure:
            # Underbid relative to their high bids to exploit their tendency
            target = DAILY_SALARY * (0.45 + 0.15 * (1.0 - supply_ratio))
        else:
            target = DAILY_SALARY * (0.55 + 0.1 * (1.0 - supply_ratio))

    # If we have many no-water days, increase urgency
    no_water_days = my_status.get('no_water_days', 0)
    if no_water_days >= 2:
        target *= 1.15
    if no_water_days >= 4:
        target *= 1.25

    # Final clamp to budget and non-negative
    budget = float(my_status.get('budget', 0.0))
    if budget <= 0.0:
        return 0.0
    if target < 0.0:
        target = 0.0
    if target > budget:
        target = budget

    return float(target)
